/// Replaces GitHub emoji shortcodes (`:tada:`) in text with `emoji` nodes (#10).
///
/// Aliases come from github/gemoji (`EmojiShortcodes.table`, generated by `make emoji`) and are
/// case-sensitive. Unknown aliases and GitHub's image-only emoji (`:octocat:`) stay literal.
///
/// Only text nodes change. Code spans and blocks, raw HTML, link destinations, and image alt
/// text (GitHub keeps `:tada:` in `alt`) are left alone, and so is the text of an autolink,
/// which is its URL.
///
/// Adjacent text nodes are matched as one run, like the DOM text github.com matches (cmark already
/// consolidates its own text nodes; this covers trees built otherwise). github.com converts a
/// run's shortcodes only when the run's first `:name:`-shaped candidate (known or not) starts the
/// run or follows a space; then every known shortcode in the run converts, wherever it is. So
/// `x :tada:`, `**:tada:**`, `:a::b:`, and `:nope:tada:` (`:nope` then the emoji) convert, as
/// does `x:tada:` after `a :tada: b`; `x:tada:`, `(:tada:)`, `:::tada:`, and
/// `x:tada: :tada:` on their own stay literal. Verified against GitHub's API (see
/// `EmojiShortcodeTests`). Known divergence: github.com leaves `/ :tada:` literal; mdv converts it.
enum EmojiShortcodes {
    /// Returns `root` with every shortcode in its text replaced by an `emoji` node.
    static func replace(in root: MarkdownNode) -> MarkdownNode {
        guard descends(into: root) else {
            return root
        }
        // Rebuild with an explicit stack rather than recursion, like the renderer.
        var stack = [Frame(root)]
        while let top = stack.indices.last {
            guard stack[top].nextChild < stack[top].node.children.count else {
                let frame = stack.removeLast()
                var node = frame.node
                node.children = replacingInTextRuns(frame.children)
                guard !stack.isEmpty else {
                    return node
                }
                stack[stack.count - 1].children.append(node)
                continue
            }
            let child = stack[top].node.children[stack[top].nextChild]
            stack[top].nextChild += 1
            if descends(into: child) {
                stack.append(Frame(child))
            } else {
                stack[top].children.append(child)
            }
        }
        return root
    }

    /// The pieces of `text` with its shortcodes replaced, or `nil` when it has none.
    static func replacements(in text: String) -> [Piece]? {
        let bytes = Array(text.utf8)
        // Pieces split only at ASCII colons, so these offsets are scalar boundaries. (Not always
        // Character boundaries: a combining mark may follow a colon, so slice scalars.)
        func slice(_ offsets: Range<Int>) -> String {
            let start = text.utf8.index(text.utf8.startIndex, offsetBy: offsets.lowerBound)
            let end = text.utf8.index(start, offsetBy: offsets.count)
            return String(text.unicodeScalars[start..<end])
        }
        guard let first = firstCandidate(in: bytes), first == 0 || bytes[first - 1] == space else {
            return nil
        }
        var pieces: [Piece] = []
        var literalStart = 0
        var index = first
        while index < bytes.count {
            guard bytes[index] == colon, let end = aliasEnd(at: index, in: bytes),
                case let alias = slice((index + 1)..<end), let character = table[alias]
            else {
                index += 1
                continue
            }
            if literalStart < index {
                pieces.append(.text(slice(literalStart..<index)))
            }
            pieces.append(.emoji(shortcode: alias, character: character))
            index = end + 1
            literalStart = index
        }
        guard !pieces.isEmpty else {
            return nil
        }
        if literalStart < bytes.count {
            pieces.append(.text(slice(literalStart..<bytes.count)))
        }
        return pieces
    }

    enum Piece: Equatable {
        case text(String)
        case emoji(shortcode: String, character: String)
    }

    // MARK: - Private

    private struct Frame {
        var node: MarkdownNode
        var nextChild = 0
        var children: [MarkdownNode] = []

        init(_ node: MarkdownNode) {
            self.node = node
            children.reserveCapacity(node.children.count)
        }
    }

    private static let colon = UInt8(ascii: ":")
    private static let space = UInt8(ascii: " ")

    /// Whether `node`'s children may hold text to replace.
    private static func descends(into node: MarkdownNode) -> Bool {
        switch node.kind {
        case .image:
            false
        case .link(let destination, _):
            !isAutolink(node, destination: destination)
        default:
            !node.children.isEmpty
        }
    }

    /// A link whose only child is text naming its own destination: a GFM extended autolink
    /// (`https://…`, `www.…`, an email address) or a `<…>` autolink.
    private static func isAutolink(_ link: MarkdownNode, destination: String) -> Bool {
        guard link.children.count == 1, case .text(let text) = link.children[0].kind else {
            return false
        }
        return destination == text || destination == "http://" + text || destination == "mailto:" + text
    }

    /// The index of the first colon that opens an alias-shaped `:name:`, known or not.
    private static func firstCandidate(in bytes: [UInt8]) -> Int? {
        bytes.indices.first { bytes[$0] == colon && aliasEnd(at: $0, in: bytes) != nil }
    }

    /// For the colon at `start`, the index of the colon closing a non-empty run of alias
    /// characters after it, or `nil` when none does.
    private static func aliasEnd(at start: Int, in bytes: [UInt8]) -> Int? {
        var end = start + 1
        while end < bytes.count, isAliasByte(bytes[end]) {
            end += 1
        }
        return end > start + 1 && end < bytes.count && bytes[end] == colon ? end : nil
    }

    /// gemoji aliases use only `a-z`, `0-9`, `_`, `+`, and `-` (checked by the generator).
    private static func isAliasByte(_ byte: UInt8) -> Bool {
        switch byte {
        case UInt8(ascii: "a")...UInt8(ascii: "z"), UInt8(ascii: "0")...UInt8(ascii: "9"),
            UInt8(ascii: "_"), UInt8(ascii: "+"), UInt8(ascii: "-"):
            true
        default:
            false
        }
    }

    /// Replaces shortcodes in each run of adjacent text nodes. A run without shortcodes is kept
    /// as is; one with shortcodes becomes alternating text and emoji nodes, each carrying the
    /// run's source range.
    private static func replacingInTextRuns(_ children: [MarkdownNode]) -> [MarkdownNode] {
        guard children.contains(where: \.kind.isText) else {
            return children
        }
        var result: [MarkdownNode] = []
        result.reserveCapacity(children.count)
        var index = 0
        while index < children.count {
            guard children[index].kind.isText else {
                result.append(children[index])
                index += 1
                continue
            }
            var end = index
            var text = ""
            while end < children.count, case .text(let literal) = children[end].kind {
                text += literal
                end += 1
            }
            let run = children[index..<end]
            if let pieces = replacements(in: text) {
                let range = sourceRange(of: run)
                result += pieces.map { piece in
                    switch piece {
                    case .text(let literal):
                        MarkdownNode(.text(literal), sourceRange: range)
                    case .emoji(let shortcode, let character):
                        MarkdownNode(.emoji(shortcode: shortcode, character: character), sourceRange: range)
                    }
                }
            } else {
                result += run
            }
            index = end
        }
        return result
    }

    private static func sourceRange(of run: ArraySlice<MarkdownNode>) -> SourceRange? {
        guard let start = run.first?.sourceRange?.start, let end = run.last?.sourceRange?.end else {
            return nil
        }
        return SourceRange(start: start, end: end)
    }
}

extension MarkdownNode.Kind {
    fileprivate var isText: Bool {
        if case .text = self {
            return true
        }
        return false
    }
}

extension EmojiShortcodes: MarkdownTreeTransform {
    static func apply(to root: MarkdownNode, context: TransformContext) -> MarkdownNode {
        replace(in: root)
    }
}
